const data = $input.first().json.body;
const lead = data.lead || {};
const notes = data.metadata?.notes || '';

const text = `🔥 *NUEVO LEAD CALIFICADO - SERSTORM*\n\n` +
  `👤 *Nombre:* ${lead.name || 'Sin nombre'}\n` +
  `🏨 *Empresa:* ${lead.company_name || 'No especificada'}\n` +
  `📱 *Teléfono:* ${lead.phone || 'N/A'}\n` +
  `📝 *Notas IA:* ${notes}\n\n` +
  `👉 Ingresá al CRM para ver el chat.`;

return [{ json: { text, lead, event: 'lead_qualified' } }];

const data = $input.first().json.body;
const lead = data.lead || {};
const datetime = data.metadata?.datetime || 'Por coordinar';

const text = `📅 *AUDITORÍA AGENDADA CON PABLO DIZ* 🚀\n\n` +
  `👤 *Cliente:* ${lead.name || 'Sin nombre'}\n` +
  `🏨 *Empresa:* ${lead.company_name || 'N/A'}\n` +
  `📱 *WhatsApp:* ${lead.phone || 'N/A'}\n` +
  `⏰ *Horario:* ${datetime}\n\n` +
  `✅ Preparar ficha técnica de pauta/SEO para la videollamada.`;

return [{ json: { text, lead, event: 'audit_booked' } }];

const data = $input.first().json.body;
const lead = data.lead || {};
const reason = data.metadata?.reason || 'Solicitud de cliente';

const text = `⚠️ *DERIVACIÓN URGENTE A ASESOR HUMANO*\n\n` +
  `📱 *WhatsApp:* ${lead.phone || data.conversation_id}\n` +
  `💬 *Motivo:* ${reason}\n\n` +
  `👉 Por favor responder desde la app de WhatsApp o desde el Panel CRM SerStorm.`;

return [{ json: { text, lead, event: 'human_handoff' } }];
